#### 1. Feedback Overlay (50% Pane Preview) vs Hit Target (20% Edge Strip)

```tsx
// ui/src/components/tab-dnd/SplitEdgeDropZone.feedbackGeometry.test.tsx
import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

const overIds = vi.hoisted(() => new Set<string>());

vi.mock("@dnd-kit/core", () => ({
  useDroppable: ({ id }: { id: string }) => ({
    setNodeRef: vi.fn(),
    isOver: overIds.has(id),
  }),
}));

import { SplitEdgeDropZone } from "./SplitEdgeDropZone";

afterEach(() => {
  cleanup();
  overIds.clear();
});

describe("SplitEdgeDropZone feedback geometry contract", () => {
  it("keeps hit target as an edge strip (20%) but renders drop preview overlay covering exactly half (50%) when hovered", () => {
    overIds.add("pane-edge:tab-1:leaf-1:left");

    render(
      <div style={{ width: 800, height: 600 }} className="relative">
        <SplitEdgeDropZone
          id="pane-edge:tab-1:leaf-1:left"
          data={{ type: "pane-edge", tabId: "tab-1", leafId: "leaf-1", edge: "left" }}
          edge="left"
          testId="pane-edge-drop-zone"
          tabId="tab-1"
          leafId="leaf-1"
        />
      </div>,
    );

    const hitTarget = screen.getByTestId("pane-edge-drop-zone");
    // Hit target must remain an edge strip (20% boundary hit zone)
    expect(hitTarget).toHaveClass("w-[20%]");
    expect(hitTarget).not.toHaveClass("w-1/2", "w-[50%]");

    // Active visual feedback preview overlay must cover exactly half (50% / w-1/2) of pane content
    const previewOverlay = screen.getByTestId("split-edge-drop-preview");
    expect(previewOverlay).toHaveClass("inset-y-0", "left-0", "w-1/2");
    expect(previewOverlay).not.toHaveClass("w-[20%]");
  });

  it("verifies top/bottom edge feedback preview spans 50% height while hit strip is 20%", () => {
    overIds.add("pane-edge:tab-1:leaf-1:bottom");

    render(
      <SplitEdgeDropZone
        id="pane-edge:tab-1:leaf-1:bottom"
        data={{ type: "pane-edge", tabId: "tab-1", leafId: "leaf-1", edge: "bottom" }}
        edge="bottom"
        testId="pane-edge-drop-zone"
        tabId="tab-1"
        leafId="leaf-1"
      />,
    );

    const hitTarget = screen.getByTestId("pane-edge-drop-zone");
    expect(hitTarget).toHaveClass("h-[20%]");

    const previewOverlay = screen.getByTestId("split-edge-drop-preview");
    expect(previewOverlay).toHaveClass("bottom-0", "inset-x-0", "h-1/2");
  });
});
```

