#### 2. Native Webview Visibility & Non-Interception During Tab/Pane Drag

```tsx
// ui/src/components/TerminalSplitView.browserDragOcclusion.runtime.test.tsx
import { cleanup, render } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const browserMocks = vi.hoisted(() => ({
  setBrowserBounds: vi.fn(async () => undefined),
  setBrowserVisible: vi.fn(async () => undefined),
}));

vi.mock("../lib/browserTauri", () => browserMocks);

const dndHarness = vi.hoisted(() => ({
  props: null as null | {
    onDragStart?: (event: unknown) => void;
    onDragEnd?: (event: unknown) => void;
    onDragCancel?: (event: unknown) => void;
  },
}));

vi.mock("@dnd-kit/core", () => ({
  DndContext: (props: any) => {
    dndHarness.props = props;
    return props.children;
  },
  DragOverlay: ({ children }: any) => children,
  KeyboardSensor: function KeyboardSensor() {},
  PointerSensor: function PointerSensor() {},
  pointerWithin: vi.fn(() => []),
  useDraggable: () => ({ setNodeRef: vi.fn(), attributes: {}, listeners: {}, isDragging: false }),
  useDroppable: () => ({ setNodeRef: vi.fn(), isOver: false }),
  useSensor: vi.fn(() => ({})),
  useSensors: vi.fn(() => []),
}));

import type { BrowserTab, LayoutState, TerminalTab } from "../lib/types";
import { TerminalSplitView } from "./TerminalSplitView";

afterEach(() => {
  cleanup();
  dndHarness.props = null;
});

describe("TerminalSplitView native webview occlusion suppression during drag", () => {
  beforeEach(() => {
    browserMocks.setBrowserBounds.mockClear();
    browserMocks.setBrowserVisible.mockClear();
  });

  it("temporarily hides native webview on drag start and restores visibility on drag end/cancel", async () => {
    const browserTab: BrowserTab = {
      kind: "browser",
      id: "tab-browser",
      label: "Browser",
      browserId: "browser-native-1",
      url: "https://example.com",
    };
    const terminalTab: TerminalTab = {
      kind: "terminal",
      id: "tab-term",
      label: "Terminal",
      sessionId: "sess-1",
    };

    const layout: LayoutState = {
      tabs: [browserTab, terminalTab],
      activeTabId: "tab-browser",
      tabGroups: {
        "g-main": { id: "g-main", tabIds: ["tab-browser", "tab-term"], activeTabId: "tab-browser" },
      },
      tabGroupLayout: { type: "group", groupId: "g-main" },
      focusedGroupId: "g-main",
    };

    render(
      <TerminalSplitView
        layout={layout}
        sessions={{}}
      />,
    );

    // Initial mount: webview is made visible
    expect(browserMocks.setBrowserVisible).toHaveBeenCalledWith("browser-native-1", true);

    // Drag starts (e.g. user drags terminal tab or pane)
    dndHarness.props!.onDragStart!({
      active: {
        data: {
          current: {
            type: "tab",
            tabId: "tab-term",
            groupId: "g-main",
            index: 1,
          },
        },
      },
    });

    // Native webview must be hidden so it does not intercept pointer events or occlude DnD overlays
    expect(browserMocks.setBrowserVisible).toHaveBeenLastCalledWith("browser-native-1", false);

    // Drag ends
    dndHarness.props!.onDragEnd!({
      over: null,
    });

    // Native webview visibility must be restored
    expect(browserMocks.setBrowserVisible).toHaveBeenLastCalledWith("browser-native-1", true);
  });
});
